INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "桑维翰", "aliases": ["桑維翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：桑维翰，主张自全、求援者。", "biography": null, "status": "draft", "id": "5132e50a-3ce2-55d5-8f89-fdccd6bf4f02"}, {"name": "杨昭俭", "aliases": ["楊昭儉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：杨昭俭，补阙、请加罪者。", "biography": null, "status": "draft", "id": "989514a0-e703-59b0-bf2a-a7ad17ff7fe5"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "折从远", "aliases": ["折從遠", "折从阮", "折從阮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "云州人，府州刺史。后晋割让北地后，府州归属契丹。他据险抵制契丹迁民，后奉石重贵命令攻入契丹境内、拔十余寨，944年六月戊午任府州团练使。《新五代史》明确其后因避汉高祖名改称折从阮，字可久。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "500d7480-2e3a-5553-9370-8e4295db3cc1"}, {"name": "折嗣伦", "aliases": ["折嗣倫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "折从远之父，《新五代史》折从阮传记为麟州刺史。任官具体年月和生卒年未载。", "biography": null, "status": "draft", "id": "8fcbb81f-5683-53ae-8ace-cdf6d94f483d"}, {"name": "李慎仪", "aliases": ["李慎儀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋右散骑常侍。944年六月戊辰任兵部侍郎、翰林学士承旨。生卒年本段未载。", "biography": null, "status": "draft", "id": "3722cf17-519f-5bba-9fba-81f696640ceb"}, {"name": "刘温叟", "aliases": ["劉溫叟"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋都官郎中，944年六月戊辰任翰林学士。刘岳之子，《宋史》刘温叟传记其字永龄、河南洛阳人。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "9b29dd8c-cc4e-5265-a209-0d78247877af"}, {"name": "徐台符", "aliases": ["徐臺符"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "武强人，后晋金部郎中、知制诰。944年六月戊辰任翰林学士。生卒年本段未载。", "biography": null, "status": "draft", "id": "28c5a951-7fb9-591a-b527-988ede5145c7"}, {"name": "李澣", "aliases": ["李浣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李涛的弟弟，后晋翰林学士。《资治通鉴》说他多次酒后失当，石敬瑭不喜欢他；940年九月翰林学士职务被撤销、事务归中书舍人。《旧五代史》同期学士名写李浣，另记他调吏部员外郎，保留字形说明。生卒年未载。", "biography": null, "status": "draft", "id": "cc1a8d2a-5333-5d3b-befa-dea7a7c759a6"}, {"name": "范质", "aliases": ["范質", "範質"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "宗城人，后晋主客员外郎。944年六月戊辰任翰林学士。后续仕宦随编年主线补录。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "abe2c0af-4bf3-551b-83c9-f355ba085a0e"}, {"name": "刘岳", "aliases": ["劉嶽", "劉岳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：刘岳。", "biography": null, "status": "draft", "id": "eb509878-35d1-5cbf-8cf9-b508d79f4d59"}, {"name": "刘昫", "aliases": ["劉昫", "刘煦", "劉煦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘昫，端明殿学士、受相职者。", "biography": null, "status": "draft", "id": "b63eeed9-ecc3-575d-aba8-41b03e6caa3e"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "张从恩", "aliases": ["張從恩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，曾任澶州防御使。939年正月任后晋枢密副使。生卒年未载。", "biography": null, "status": "draft", "id": "e1e909ad-c88c-54a5-941c-6116c704a870"}, {"name": "景延广", "aliases": ["景延廣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：景延广，原客将、获任者。", "biography": null, "status": "draft", "id": "de8a964e-a028-50ee-8d54-2cbfda481e98"}, {"name": "赵在礼", "aliases": ["趙在禮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：赵在礼。", "biography": null, "status": "draft", "id": "90ff68a5-70f2-5182-8802-93859bae2990"}, {"name": "安叔千", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安叔千，原易州刺史、振武节度使获任者。", "biography": null, "status": "draft", "id": "ee67f0c1-6366-5021-a802-f74b89714b11"}, {"name": "安审信", "aliases": ["安審信"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安审信，西北先锋马军都指挥使、转投者。", "biography": null, "status": "draft", "id": "d2ddf941-57f6-5dc2-bf1b-d0256df4eae0"}, {"name": "安审琦", "aliases": ["安審琦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安审琦，彰圣都指挥使、领顺化节度使者。", "biography": null, "status": "draft", "id": "a579a6a1-65a5-5c8a-9c6c-be178cb049aa"}, {"name": "符彦卿", "aliases": ["符彥卿", "李彦卿", "李彥卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：符彦卿，散员都指挥使、力战者。", "biography": null, "status": "draft", "id": "c837916f-0fdf-5954-a190-597b08cd9402"}, {"name": "皇甫遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：皇甫遇，原严卫步军都指挥使、接侍卫步军者。", "biography": null, "status": "draft", "id": "0aa52fa6-cacc-5960-8646-9ab3a0393623"}, {"name": "张彦泽", "aliases": ["張彥澤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，938年任镇国军节度使，在华州截击并杀死东行的凤翔叛军。生卒年本段未载。", "biography": null, "status": "draft", "id": "194d0f9a-3b17-5635-9741-dffc983ee32e"}, {"name": "王廷胤", "aliases": ["王庭胤", "王庭允"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王处存的孙子，曾任贝州防御使。938年任彰德军节度使。《旧五代史》传记作王庭胤，记他字绍基，祖籍长安；同一传记及任官纪事又作王庭允。", "biography": null, "status": "draft", "id": "84bebd8d-f76c-5a88-8a58-3932dce9cb0c"}, {"name": "宋彦筠", "aliases": ["宋彥筠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋前同州节度使，滑州人。941年十一月丁丑受任高行周的副将，参与南面军前讨伐安从进的部署。生卒年未载。", "biography": null, "status": "draft", "id": "a66a316a-5777-5c2c-aaa8-0e523f85477d"}, {"name": "田武", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋前金州节度使。944年八月在北面行营任步军左厢排阵使，参与对契丹的军职部署。生卒年本段未载。", "biography": null, "status": "draft", "id": "ec6dab9c-48ff-5f2f-98f1-3ed911c9c14d"}, {"name": "潘环", "aliases": ["潘環", "潘瑰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：潘环，王村寨守将、奔梁者。", "biography": null, "status": "draft", "id": "5e093bc1-94d3-542b-ac05-e1f1184aa8ba"}, {"name": "冯晖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷263天复二年条所见人物：冯晖。", "biography": null, "status": "draft", "id": "e59e2b00-2873-5968-ab4c-938628164ecf"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "朱文进", "aliases": ["硃文进", "朱文進", "硃文進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "永泰人，闽国拱宸军将领。《资治通鉴》记他与连重遇多次受王继鹏侮辱而心怀不满，《新五代史》还记二人因宸卫军待遇优厚而激怒部众。生卒年未载。", "biography": null, "status": "draft", "id": "309ef83c-46fe-51a1-86cc-c2cb8dc48d82"}]'::jsonb)
